import {
  BigNumber,
  ChartHeader,
  ContentCard,
  DataStateHandler,
  Skeleton,
} from 'components';
import { BigNumberOrientation } from 'components/BigNumber/types';
import { VALUE_CREATION_TREND_COLORS } from 'pages/pillars/ValueCreation/PerformanceTool/constants';
import { BigNumbersSectionData } from 'pages/pillars/ValueCreation/PerformanceTool/types';

import {
  StyledBigNumberFooter,
  StyledBigNumbersContainer,
  StyledEmbeddedBigNumbersWrapper,
} from './BigNumbersSection.styles';

type BigNumbersSectionVariant = 'default' | 'embedded';

interface BigNumbersSectionProps {
  title: string;
  tooltip?: string;
  data?: BigNumbersSectionData[];
  loading: boolean;
  error: Error | null;
  orientation?: BigNumberOrientation;
  skeletonProps?: React.ComponentProps<typeof Skeleton>;
  onSelect?: (index: number) => void;
  defaultSelected?: number;
  variant?: BigNumbersSectionVariant;
}

export const BigNumbersSection: React.FC<BigNumbersSectionProps> = ({
  title,
  tooltip,
  loading,
  error,
  data,
  orientation = 'vertical',
  skeletonProps = {
    height: '168px',
    width: '100%',
    length: 2,
    borderRadius: 'medium',
  },
  onSelect,
  defaultSelected = 0,
  variant = 'default',
}) => {
  const content = loading ? (
    <StyledBigNumbersContainer data-testid="big-numbers-container">
      <Skeleton {...skeletonProps} width="100%" hasContainer={false} />
    </StyledBigNumbersContainer>
  ) : (
    <DataStateHandler
      loading={false}
      error={error}
      empty={!data || data.length === 0}
    >
      <StyledBigNumbersContainer data-testid="big-numbers-container">
        {data?.map((bigNumber, index) => (
          <BigNumber
            key={bigNumber.header.title}
            className="performance-tool-big-number"
            header={
              <ChartHeader
                title={bigNumber.header.title}
                config={{ inline: 'horizontal', type: 'large' }}
              />
            }
            data={bigNumber.data}
            size="medium"
            asCard
            spacing="loose"
            orientation={orientation}
            alignment="center"
            fullWidth
            onClick={() => onSelect?.(index)}
            isSelected={defaultSelected === index}
            enableTruncation
            trendColors={VALUE_CREATION_TREND_COLORS}
            footer={
              <StyledBigNumberFooter>
                <p>{bigNumber.footer?.value}</p>{' '}
                <span>{bigNumber.footer?.label}</span>
              </StyledBigNumberFooter>
            }
          />
        ))}
      </StyledBigNumbersContainer>
    </DataStateHandler>
  );

  if (variant === 'embedded') {
    return (
      <StyledEmbeddedBigNumbersWrapper data-testid="embedded-big-numbers-wrapper">
        {content}
      </StyledEmbeddedBigNumbersWrapper>
    );
  }

  return (
    <ContentCard fullWidth title={title} tooltip={tooltip}>
      {content}
    </ContentCard>
  );
};
